reproduction_script_gd:
extends SceneTree
const Actor=preload("res://scripts/dungeon_actor.gd")
var report:Array=[]
func _initialize() -> void: run_trace.call_deferred()
func vector(p:Vector3) -> Array: return [p.x,p.y,p.z]
func run_trace() -> void:
	for fps in [30,60,120]:
		for key in ["Arcanist","Ranger"]:
			for style in ["basic","signature"]:
				var actor:Node3D=Actor.new();actor.kind=key;root.add_child(actor);actor.animate(.15,false)
				actor.strike(style,.30,true)
				var clip_source=actor.Rig.Clips
				var max_support:=0.0;var max_rear:=0.0;var max_support_height:=0.0;var release_gap:=0.0;var stable:=true;var samples:Array=[]
				for frame in range(1,int(.6*fps)+1):
					var elapsed:float=float(frame)/float(fps)
					actor.sync_attack(maxf(0.0,.30-elapsed));actor.animate(1.0/fps,false)
					if elapsed>=.215 and actor.release_time<0.0 and actor.attack_time>=0.0:
						var before:Vector3=actor.projectile_origin();actor.release_attack();release_gap=before.distance_to(actor.projectile_origin())
					var acting:bool=actor.last_clip.begins_with("windup") or actor.last_clip.begins_with("recover")
					if not acting:continue
					var phase:float=actor.release_time/.34 if actor.release_time>=0 else clampf(actor.attack_time/.215,0,1)
					var row:Dictionary={"frame":frame,"seconds":elapsed,"release":actor.release_time,"clip":actor.last_clip,"phase":phase,"feet":[]}
					for side in range(2):
						var actual:Vector3=actor.motion_rig.skeleton.get_bone_global_pose(14 if side==0 else 17).origin
						var target:Vector3=clip_source.action_foot(key,actor.last_clip,phase,side)
						var support:bool=clip_source.action_support(key,actor.last_clip,phase,side)
						var error:=actual.distance_to(target)
						if support:max_support=maxf(max_support,error);max_support_height=maxf(max_support_height,absf(actual.y-target.y))
						if side==1:max_rear=maxf(max_rear,error)
						row.feet.append({"side":side,"support":support,"target":vector(target),"actual":vector(actual),"error":error})
					stable=stable and actor.position==Vector3.ZERO
					samples.append(row)
				report.append({"fps":fps,"class":key,"style":style,"max_supported_foot_error":max_support,"max_supported_foot_height_error":max_support_height,"max_rear_support_error":max_rear,"release_emitter_gap":release_gap,"actor_fixed":stable,"samples":samples})
				actor.free()
	var output:="user://bodyphrase-049-contact.json"
	for argument in OS.get_cmdline_user_args():
		if argument.begins_with("--output="):output=argument.trim_prefix("--output=")
	var file:=FileAccess.open(output,FileAccess.WRITE);file.store_string(JSON.stringify(report,"  "))
	print("CONTACT_TRACE ",report.size()," ordinary-clock cases");quit()
